import{_ as g,I as a,o as b,c as k,b6 as p,J as t,j as n,a as l}from"./chunks/framework.COUcLbTA.js";const x=JSON.parse('{"title":"从按下电源到访问网站发生了什么","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/1-computer-fundamentals/power-on-to-web.md","filePath":"zh-cn/appendix/1-computer-fundamentals/power-on-to-web.md"}'),u={name:"zh-cn/appendix/1-computer-fundamentals/power-on-to-web.md"};function _(T,s,P,m,S,C){const e=a("PowerOnDemo"),i=a("BiosUefiInteractiveDemo"),o=a("OSBootInteractiveDemo"),r=a("BrowserArchitectureDemo"),d=a("URLRequestDemo"),c=a("RenderingDemo"),h=a("FullProcessDemo");return b(),k("div",null,[s[0]||(s[0]=p('<h1 id="从按下电源到访问网站发生了什么" tabindex="-1">从按下电源到访问网站发生了什么 <a class="header-anchor" href="#从按下电源到访问网站发生了什么" aria-label="Permalink to “从按下电源到访问网站发生了什么”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p>你有没有想过，当你按下电脑电源键，到最终在浏览器中看到网页，这中间到底发生了什么？</p><p>这个过程就像一场<strong>接力赛</strong>——硬件通电后唤醒固件，固件检查完毕后交棒给操作系统，操作系统准备好环境后才能运行浏览器，浏览器再通过网络去远方的服务器取回网页。每一个环节都<strong>依赖上一个环节的成功完成</strong>，任何一棒掉链子，后面的步骤都无法进行。</p><p>理解这条完整的链路，能帮助你建立对计算机系统的整体认知，也是成为全栈工程师的必经之路。</p></div><p><strong>你会学到什么？</strong></p><p>这篇文章按照事件发生的真实顺序，带你走完从按下电源到看到网页的五个阶段：</p><ol><li><strong>硬件启动</strong>（第 1 节）→ 电流如何唤醒 CPU</li><li><strong>固件自检</strong>（第 2 节）→ BIOS/UEFI 如何确认硬件正常并找到启动设备</li><li><strong>操作系统启动</strong>（第 3 节）→ 内核如何加载、桌面如何出现</li><li><strong>浏览器启动</strong>（第 4 节）→ 应用程序如何被操作系统运行起来</li><li><strong>网络请求</strong>（第 5 节）→ 从输入 URL 到页面渲染的完整网络之旅</li></ol><p>每一步都建立在前一步的基础上，缺一不可。</p><hr><h2 id="_1-按下电源-硬件的觉醒" tabindex="-1">1. 按下电源：硬件的觉醒 <a class="header-anchor" href="#_1-按下电源-硬件的觉醒" aria-label="Permalink to “1. 按下电源：硬件的觉醒”">​</a></h2><h3 id="_1-1-电源启动" tabindex="-1">1.1 电源启动 <a class="header-anchor" href="#_1-1-电源启动" aria-label="Permalink to “1.1 电源启动”">​</a></h3><p>当你按下电源键，<strong>电源单元（PSU）</strong> 开始工作，把交流电（220V）转换成直流电（12V、5V、3.3V 等），为各个硬件部件供电。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>电源按钮 → 电源单元(PSU) → 直流电输出 → 供给主板各部件</span></span></code></pre></div><h3 id="_1-2-主板芯片组唤醒" tabindex="-1">1.2 主板芯片组唤醒 <a class="header-anchor" href="#_1-2-主板芯片组唤醒" aria-label="Permalink to “1.2 主板芯片组唤醒”">​</a></h3><p>电源稳定后，<strong>主板芯片组</strong>开始工作，它就像电脑的&quot;总调度员&quot;，负责协调各个硬件部件。</p><h3 id="_1-3-cpu-复位" tabindex="-1">1.3 CPU 复位 <a class="header-anchor" href="#_1-3-cpu-复位" aria-label="Permalink to “1.3 CPU 复位”">​</a></h3><p>CPU 接收到复位信号后，把内部所有寄存器和缓存清零，从一个预设的地址开始执行指令。这个地址通常指向 <strong>BIOS/UEFI</strong> 芯片。</p>',15)),t(e),s[1]||(s[1]=p('<hr><blockquote><p><strong>接力第一棒完成</strong> ⛳ 到这里，硬件层面的工作已经完成：电源把交流电转成了稳定的直流电，主板芯片组被唤醒并开始协调各部件，CPU 也完成了复位、清空了寄存器，准备好执行第一条指令。</p><p>但请注意——此刻的 CPU 就像一个&quot;刚睁开眼的婴儿&quot;。它虽然能执行指令，却对自己所在的环境一无所知：电脑里装了多少内存？显卡能不能用？硬盘在哪里？该从哪个设备启动操作系统？这些问题 CPU 自己回答不了。</p><p>所以，CPU 复位后执行的第一条指令，就是跳转到一个<strong>固定的内存地址</strong>——这个地址指向主板上焊死的 BIOS/UEFI 固件芯片。从这一刻起，控制权从纯硬件交到了固件手中。BIOS/UEFI 的任务很明确：<strong>检查所有硬件是否正常，然后找到操作系统并把它启动起来</strong>。这就是接力赛的第二棒。</p></blockquote><h2 id="_2-bios-uefi-硬件的自检" tabindex="-1">2. BIOS/UEFI：硬件的自检 <a class="header-anchor" href="#_2-bios-uefi-硬件的自检" aria-label="Permalink to “2. BIOS/UEFI：硬件的自检”">​</a></h2>',3)),t(i),s[2]||(s[2]=n("hr",null,null,-1)),s[3]||(s[3]=n("blockquote",null,[n("p",null,[n("strong",null,"接力第二棒完成"),l(" ⛳ BIOS/UEFI 圆满完成了它的三项使命：通过 POST 自检确认内存、显卡、键盘等硬件全部工作正常；初始化各硬件的工作模式；按照启动顺序找到了硬盘上的启动扇区。")]),n("p",null,[l('但 BIOS/UEFI 的角色到此为止——它本质上是一个"体检医生 + 调度员"。它能检查硬件健不健康、能决定从哪个设备启动，但它不会管理你的文件，不会运行你的应用程序，也不会给你显示一个漂亮的桌面。这些复杂的任务，需要一个更强大的软件来接管——那就是'),n("strong",null,"操作系统"),l("。")]),n("p",null,"交接的方式很具体：BIOS/UEFI 读取硬盘第一个扇区（启动扇区）里的引导程序代码，把它加载到内存中，然后让 CPU 跳转到这段代码开始执行。从这一刻起，控制权正式从固件交给了操作系统的引导程序。引导程序会一步步把操作系统内核加载进来，启动系统服务，最终呈现出你熟悉的桌面。这条链路中最复杂的一棒，开始了。")],-1)),s[4]||(s[4]=n("h2",{id:"_3-操作系统启动-从内核到桌面",tabindex:"-1"},[l("3. 操作系统启动：从内核到桌面 "),n("a",{class:"header-anchor",href:"#_3-操作系统启动-从内核到桌面","aria-label":"Permalink to “3. 操作系统启动：从内核到桌面”"},"​")],-1)),t(o),s[5]||(s[5]=p(`<hr><blockquote><p><strong>接力第三棒完成</strong> ⛳ 操作系统已经完全启动，桌面呈现在你眼前。回顾一下这一棒做了什么：引导程序从硬盘读取内核、内核接管了 CPU 和内存的控制权、系统服务逐个启动（网络、音频、安全中心……）、最后图形界面渲染出桌面。</p><p>此刻的操作系统就像一座已经通水通电、物业入驻的大楼——<strong>进程管理</strong>负责给每个住户（程序）分配房间，<strong>内存管理</strong>负责分配空间，<strong>文件系统</strong>负责管理仓库，<strong>网络协议栈</strong>负责对外通信。这些&quot;公共服务&quot;是所有应用程序运行的基础设施，没有它们，任何程序都无法启动。</p><p>现在你想上网，于是双击了桌面上的浏览器图标。这个简单的动作背后，操作系统要做一系列工作：查找浏览器的可执行文件在硬盘的哪个位置、为它创建一个独立的进程、分配内存空间、加载程序代码……这就是操作系统&quot;进程管理&quot;能力的直接体现。接下来，让我们看看浏览器是如何被启动起来的。</p></blockquote><h2 id="_4-打开浏览器-应用程序的启动" tabindex="-1">4. 打开浏览器：应用程序的启动 <a class="header-anchor" href="#_4-打开浏览器-应用程序的启动" aria-label="Permalink to “4. 打开浏览器：应用程序的启动”">​</a></h2><h3 id="_4-1-应用程序的启动过程" tabindex="-1">4.1 应用程序的启动过程 <a class="header-anchor" href="#_4-1-应用程序的启动过程" aria-label="Permalink to “4.1 应用程序的启动过程”">​</a></h3><p>当你双击浏览器图标时，操作系统会：</p><ol><li><strong>查找可执行文件</strong>：根据文件关联，找到浏览器的 <code>.exe</code>（Windows）或可执行文件</li><li><strong>创建进程</strong>：为浏览器创建一个新的<strong>进程</strong></li><li><strong>加载程序</strong>：把浏览器的代码从硬盘加载到内存</li><li><strong>初始化</strong>：启动浏览器的主线程、渲染引擎、网络引擎等</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器启动过程：</span></span>
<span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. 双击图标                        │</span></span>
<span class="line"><span>│  2. 操作系统查找浏览器可执行文件     │</span></span>
<span class="line"><span>│  3. 创建浏览器进程                  │</span></span>
<span class="line"><span>│  4. 加载浏览器代码到内存             │</span></span>
<span class="line"><span>│  5. 初始化各模块（渲染、网络、JS）   │</span></span>
<span class="line"><span>│  6. 显示浏览器窗口                   │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><h3 id="_4-2-浏览器的主要组成部分" tabindex="-1">4.2 浏览器的主要组成部分 <a class="header-anchor" href="#_4-2-浏览器的主要组成部分" aria-label="Permalink to “4.2 浏览器的主要组成部分”">​</a></h3><p>现代浏览器是一个复杂的&quot;操作系统&quot;，主要由以下部分组成：</p><table tabindex="0"><thead><tr><th>模块</th><th>功能</th></tr></thead><tbody><tr><td><strong>用户界面</strong></td><td>地址栏、标签页、书签等</td></tr><tr><td><strong>浏览器引擎</strong></td><td>协调 UI 和渲染引擎</td></tr><tr><td><strong>渲染引擎</strong></td><td>解析 HTML/CSS，显示网页</td></tr><tr><td><strong>JavaScript 引擎</strong></td><td>执行 JavaScript 代码</td></tr><tr><td><strong>网络模块</strong></td><td>发送 HTTP 请求</td></tr><tr><td><strong>UI 后端</strong></td><td>绘制基础 UI 组件</td></tr><tr><td><strong>数据存储</strong></td><td>Cookie、LocalStorage 等</td></tr></tbody></table>`,10)),t(r),s[6]||(s[6]=p(`<hr><blockquote><p><strong>接力第四棒完成</strong> ⛳ 浏览器已经成功启动。操作系统为它创建了独立的进程，分配了内存空间，浏览器自身的各个模块也已初始化完毕：渲染引擎准备好解析 HTML/CSS，JavaScript 引擎准备好执行脚本，网络模块准备好发送和接收数据。</p><p>你可以把此刻的浏览器想象成一辆已经发动的汽车——引擎在运转、仪表盘亮起、导航系统就绪，但车还停在原地，因为司机（你）还没有告诉它&quot;去哪里&quot;。浏览器窗口此刻是空白的，地址栏闪烁着光标，等待你的输入。</p><p>当你在地址栏敲入 <code>https://www.example.com</code> 并按下回车，一场跨越整个互联网的旅程就开始了。浏览器的网络模块会接管这个请求：先解析 URL 的结构，再通过 DNS 把域名翻译成 IP 地址，然后跨越网络与远方的服务器建立 TCP 连接，协商加密通道，发送 HTTP 请求，等待服务器响应，最后把收到的 HTML/CSS/JS 代码交给渲染引擎绘制成你看到的网页。这是整条接力链中步骤最多、涉及协议最丰富的一棒——也是 Web 开发者最需要理解的一段。</p></blockquote><h2 id="_5-访问-url-网络请求的全过程" tabindex="-1">5. 访问 URL：网络请求的全过程 <a class="header-anchor" href="#_5-访问-url-网络请求的全过程" aria-label="Permalink to “5. 访问 URL：网络请求的全过程”">​</a></h2><h3 id="_5-1-什么是-url" tabindex="-1">5.1 什么是 URL？ <a class="header-anchor" href="#_5-1-什么是-url" aria-label="Permalink to “5.1 什么是 URL？”">​</a></h3><p><strong>URL（Uniform Resource Locator）</strong> 是资源的地址，就像生活中的地址一样，用来定位互联网上的资源。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>URL 的结构：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  https://  │  www.example.com  │  /path/to/page  │ ?query=1 │</span></span>
<span class="line"><span>│    协议    │       域名        │     路径       │   查询   │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>协议（Protocol）</strong>：用什么方式访问（http、https、ftp 等）</li><li><strong>域名（Domain）</strong>：服务器的地址</li><li><strong>路径（Path）</strong>：资源在服务器上的位置</li><li><strong>查询（Query）</strong>：额外的参数</li></ul><h3 id="_5-2-访问-url-的完整过程" tabindex="-1">5.2 访问 URL 的完整过程 <a class="header-anchor" href="#_5-2-访问-url-的完整过程" aria-label="Permalink to “5.2 访问 URL 的完整过程”">​</a></h3><p>当你访问 <code>https://www.example.com</code> 时，发生了这些事情：</p>`,9)),t(d),s[7]||(s[7]=p(`<h4 id="第一步-url-解析" tabindex="-1">第一步：URL 解析 <a class="header-anchor" href="#第一步-url-解析" aria-label="Permalink to “第一步：URL 解析”">​</a></h4><p>浏览器首先<strong>解析 URL</strong>，提取出协议、域名、路径等信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>URL 解析过程：</span></span>
<span class="line"><span>https://www.example.com/index.html</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>协议: https</span></span>
<span class="line"><span>域名: www.example.com</span></span>
<span class="line"><span>路径: /index.html</span></span></code></pre></div><h4 id="第二步-dns-解析" tabindex="-1">第二步：DNS 解析 <a class="header-anchor" href="#第二步-dns-解析" aria-label="Permalink to “第二步：DNS 解析”">​</a></h4><p>计算机通过网络访问服务器，但网络用的是 <strong>IP 地址</strong>（如 93.184.216.34），而不是域名。所以需要把域名转换成 IP 地址，这个过程叫 <strong>DNS 解析</strong>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>DNS 解析流程：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  浏览器缓存 → hosts 文件 → 本地 DNS 缓存 → DNS 服务器  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实际过程：</span></span>
<span class="line"><span>1. 浏览器检查缓存（最近访问过吗？）</span></span>
<span class="line"><span>2. 操作系统检查 DNS 缓存</span></span>
<span class="line"><span>3. 向 DNS 服务器发送查询请求</span></span>
<span class="line"><span>4. DNS 服务器返回 IP 地址</span></span></code></pre></div><h4 id="第三步-建立-tcp-连接" tabindex="-1">第三步：建立 TCP 连接 <a class="header-anchor" href="#第三步-建立-tcp-连接" aria-label="Permalink to “第三步：建立 TCP 连接”">​</a></h4><p>拿到 IP 地址后，浏览器要与服务器建立 <strong>TCP 连接</strong>。TCP 是传输层协议，保证数据可靠传输。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>TCP 三次握手：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  客户端 → 服务器：SYN（同步请求）                       │</span></span>
<span class="line"><span>│  服务器 → 客户端：SYN-ACK（确认并同步）                 │</span></span>
<span class="line"><span>│  客户端 → 服务器：ACK（确认）                           │</span></span>
<span class="line"><span>│                        ↓                                │</span></span>
<span class="line"><span>│  连接建立完成！                                         │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>如果是 <strong>HTTPS</strong>，还需要进行 <strong>TLS/SSL 握手</strong>，建立加密通道。</p><h4 id="第四步-发送-http-请求" tabindex="-1">第四步：发送 HTTP 请求 <a class="header-anchor" href="#第四步-发送-http-请求" aria-label="Permalink to “第四步：发送 HTTP 请求”">​</a></h4><p>连接建立后，浏览器向服务器发送 <strong>HTTP 请求</strong>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP 请求格式：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  GET /index.html HTTP/1.1                              │</span></span>
<span class="line"><span>│  Host: www.example.com                                 │</span></span>
<span class="line"><span>│  User-Agent: Mozilla/5.0...                             │</span></span>
<span class="line"><span>│  Accept: text/html                                     │</span></span>
<span class="line"><span>│                                                         │</span></span>
<span class="line"><span>│  （空行）                                               │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>常见的 HTTP 方法：</p><table tabindex="0"><thead><tr><th>方法</th><th>含义</th><th>用途</th></tr></thead><tbody><tr><td><strong>GET</strong></td><td>获取资源</td><td>浏览网页</td></tr><tr><td><strong>POST</strong></td><td>提交数据</td><td>登录、提交表单</td></tr><tr><td><strong>PUT</strong></td><td>上传资源</td><td>文件上传</td></tr><tr><td><strong>DELETE</strong></td><td>删除资源</td><td>删除数据</td></tr></tbody></table><h4 id="第五步-服务器处理请求" tabindex="-1">第五步：服务器处理请求 <a class="header-anchor" href="#第五步-服务器处理请求" aria-label="Permalink to “第五步：服务器处理请求”">​</a></h4><p>服务器（通常是 <strong>Web 服务器</strong> 如 Nginx、Apache）收到请求后：</p><ol><li><strong>解析请求</strong>：理解客户端想要什么</li><li><strong>处理业务</strong>：调用后端程序（如 Python、Node.js、Java）</li><li><strong>查询数据库</strong>：获取需要的数据</li><li><strong>生成响应</strong>：把数据组装成 HTML、JSON 等格式</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>服务器处理流程：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. Web 服务器接收请求 (Nginx/Apache)                  │</span></span>
<span class="line"><span>│  2. 根据路径找到对应的处理程序                          │</span></span>
<span class="line"><span>│  3. 执行后端代码 (API、业务逻辑)                        │</span></span>
<span class="line"><span>│  4. 如需查询数据库，获取数据                           │</span></span>
<span class="line"><span>│  5. 组装响应 (HTML/JSON/CSS/JS)                        │</span></span>
<span class="line"><span>│  6. 返回 HTTP 响应                                     │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><h4 id="第六步-返回-http-响应" tabindex="-1">第六步：返回 HTTP 响应 <a class="header-anchor" href="#第六步-返回-http-响应" aria-label="Permalink to “第六步：返回 HTTP 响应”">​</a></h4><p>服务器返回 <strong>HTTP 响应</strong>，包含状态码、响应头和响应体：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP 响应格式：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  HTTP/1.1 200 OK                                       │</span></span>
<span class="line"><span>│  Content-Type: text/html                               │</span></span>
<span class="line"><span>│  Content-Length: 1234                                  │</span></span>
<span class="line"><span>│                                                         │</span></span>
<span class="line"><span>│  &lt;!DOCTYPE html&gt;                                       │</span></span>
<span class="line"><span>│  &lt;html&gt;...&lt;/html&gt;                                      │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>常见的状态码：</p><table tabindex="0"><thead><tr><th>状态码</th><th>含义</th></tr></thead><tbody><tr><td><strong>200</strong></td><td>成功</td></tr><tr><td><strong>301/302</strong></td><td>重定向</td></tr><tr><td><strong>404</strong></td><td>资源未找到</td></tr><tr><td><strong>500</strong></td><td>服务器错误</td></tr></tbody></table><h4 id="第七步-浏览器渲染页面" tabindex="-1">第七步：浏览器渲染页面 <a class="header-anchor" href="#第七步-浏览器渲染页面" aria-label="Permalink to “第七步：浏览器渲染页面”">​</a></h4><p>浏览器收到响应后，开始<strong>渲染页面</strong>：</p>`,26)),t(c),s[8]||(s[8]=p(`<ol><li><strong>解析 HTML</strong>：构建 DOM 树</li><li><strong>解析 CSS</strong>：计算样式，构建渲染树</li><li><strong>执行 JavaScript</strong>：执行页面中的 JS 代码</li><li><strong>绘制页面</strong>：把内容显示到屏幕上</li></ol><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器渲染过程：</span></span>
<span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. HTML 解析 → DOM 树                                │</span></span>
<span class="line"><span>│  2. CSS 解析 → 样式规则                               │</span></span>
<span class="line"><span>│  3. DOM + CSS → 渲染树                                │</span></span>
<span class="line"><span>│  4. 布局计算 → 每个元素的大小位置                      │</span></span>
<span class="line"><span>│  5. 绘制 → 像素显示到屏幕                             │</span></span>
<span class="line"><span>│  6. 合成 → 多层合并显示                                │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><blockquote><p><strong>接力最后一棒完成</strong> ⛳ 网页终于显示在你眼前了！回顾这最后一棒经历了多少环节：浏览器解析 URL 提取出协议和域名，通过 DNS 层层查询把域名翻译成 IP 地址，经过 TCP 三次握手与服务器建立可靠连接，再通过 TLS 握手建立加密通道，然后发送 HTTP 请求，服务器处理业务逻辑、查询数据库、组装响应数据返回，最后浏览器的渲染引擎把 HTML 解析成 DOM 树、CSS 计算成样式规则、两者合并成渲染树、计算布局、逐像素绘制到屏幕上。</p><p>现在，让我们把视角拉远，从头到尾审视这场接力赛的全貌。从按下电源键的那一刻算起：电流唤醒硬件（第 1 棒）→ 固件检查设备并找到启动盘（第 2 棒）→ 操作系统从内核到桌面完整启动（第 3 棒）→ 浏览器作为应用程序被操作系统运行起来（第 4 棒）→ 网络请求跨越互联网取回数据并渲染成页面（第 5 棒）。五棒环环相扣，每一棒都建立在前一棒的成果之上，缺少任何一个环节，你都无法看到眼前的这个网页。</p><p>接下来，让我们用一张完整的流程图把这五个阶段串在一起，直观地看看它们之间的依赖关系。</p></blockquote><h2 id="_6-完整流程回顾" tabindex="-1">6. 完整流程回顾 <a class="header-anchor" href="#_6-完整流程回顾" aria-label="Permalink to “6. 完整流程回顾”">​</a></h2><p>让我们把整个过程串起来：</p>`,6)),t(h),s[9]||(s[9]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>从按下电源到访问网站的完整流程：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  1. 按下电源                                                      │</span></span>
<span class="line"><span>│     └── 电源启动 → 主板唤醒 → CPU 复位 → 执行 BIOS/UEFI          │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  2. BIOS/UEFI 启动                                               │</span></span>
<span class="line"><span>│     └── 硬件自检 → 寻找启动设备 → 读取引导程序                   │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  3. 操作系统启动                                                 │</span></span>
<span class="line"><span>│     └── 引导程序 → 加载内核 → 启动服务 → 显示桌面                │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  4. 打开浏览器                                                   │</span></span>
<span class="line"><span>│     └── 双击图标 → 创建进程 → 加载程序 → 显示窗口                │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  5. 访问 URL                                                     │</span></span>
<span class="line"><span>│     └── URL 解析 → DNS 解析 → TCP 连接 → HTTP 请求              │</span></span>
<span class="line"><span>│         → 服务器处理 → HTTP 响应 → 浏览器渲染 → 显示网页          │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><blockquote><p>看完整条链路，你会发现一个有趣的规律：每个阶段解决的问题完全不同，背后涉及的技术领域也截然不同。第 1 棒是<strong>电子工程</strong>的领域——电源转换、电路设计、信号传输；第 2 棒属于<strong>固件编程</strong>——用底层代码直接操控硬件；第 3 棒是<strong>操作系统</strong>的世界——进程调度、内存管理、文件系统，这是计算机科学的核心课题；第 4 棒涉及<strong>应用开发</strong>——如何设计一个像浏览器这样复杂的软件架构；第 5 棒则横跨<strong>计算机网络</strong>和<strong>前端开发</strong>——从 DNS、TCP/IP、HTTP 等网络协议，到 HTML/CSS/JS 的解析与渲染。</p><p>这也解释了为什么&quot;全栈工程师&quot;需要广泛的知识面：你写的每一行前端代码，最终都要经过这整条链路才能呈现给用户。理解链路中的每一环，能帮助你在遇到问题时快速定位——是网络层的问题？是服务器的问题？还是浏览器渲染的问题？</p><p>下面这张知识地图把这些技术领域梳理清楚，也为你后续的深入学习指明方向。</p></blockquote><h2 id="_7-知识地图" tabindex="-1">7. 知识地图 <a class="header-anchor" href="#_7-知识地图" aria-label="Permalink to “7. 知识地图”">​</a></h2><p>这一章涉及的知识领域：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>计算机系统概览</span></span>
<span class="line"><span>├── 硬件基础</span></span>
<span class="line"><span>│   ├── 电源 (PSU)</span></span>
<span class="line"><span>│   ├── 主板芯片组</span></span>
<span class="line"><span>│   └── CPU</span></span>
<span class="line"><span>├── BIOS/UEFI</span></span>
<span class="line"><span>│   ├── POST 自检</span></span>
<span class="line"><span>│   ├── 启动顺序</span></span>
<span class="line"><span>│   └── 引导程序</span></span>
<span class="line"><span>├── 操作系统</span></span>
<span class="line"><span>│   ├── 内核 (Kernel)</span></span>
<span class="line"><span>│   ├── 系统服务</span></span>
<span class="line"><span>│   └── 桌面环境</span></span>
<span class="line"><span>├── 应用程序</span></span>
<span class="line"><span>│   ├── 进程管理</span></span>
<span class="line"><span>│   └── 程序加载</span></span>
<span class="line"><span>└── 网络通信</span></span>
<span class="line"><span>    ├── DNS 解析</span></span>
<span class="line"><span>    ├── TCP/IP 协议</span></span>
<span class="line"><span>    ├── HTTP 协议</span></span>
<span class="line"><span>    └── 浏览器渲染</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">继续学习</p><p>如果你想深入了解某个环节，可以继续学习：</p><ul><li><strong>从晶体管到 CPU</strong>：了解计算机硬件基础</li><li><strong>操作系统（进程/内存/文件系统）</strong>：深入理解操作系统</li><li><strong>计算机网络</strong>：深入理解网络协议</li></ul></div>`,7))])}const I=g(u,[["render",_]]);export{x as __pageData,I as default};
